return $input.all().map(item => {
  const data = item.json;

  // ---------- Datos básicos ----------
  const fileId = data.id || '';
  const fileName = data.name || '';
  const mimeType = data.mimeType || '';
  const size = Number(data.size) || 0;
  const extension = fileName.includes('.') 
    ? fileName.split('.').pop().toLowerCase() 
    : '';

  // ---------- Fechas ----------
  const createdDate = data.createdTime ? new Date(data.createdTime) : null;
  const modifiedDate = data.modifiedTime ? new Date(data.modifiedTime) : null;

  // Hoy a las 00:00
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Fecha de creación a las 00:00
  let isToday = false;
  let daysSinceCreation = 0;
  let isOld = false;

  if (createdDate) {
    const fileDate = new Date(createdDate);
    fileDate.setHours(0, 0, 0, 0);

    isToday = fileDate.getTime() === today.getTime();

    // Días desde la creación
    const diffTime = today.getTime() - fileDate.getTime();
    daysSinceCreation = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    // Consideramos "antiguo" si tiene más de 7 días (puedes cambiar el número)
    isOld = daysSinceCreation > 7;
  }

  return {
    json: {
      id: fileId,
      Nombre: fileName,
      Tipo: mimeType,
      Extension: extension,
      Tamaño_bytes: size,
      Tamaño_MB: size > 0 ? (size / 1048576).toFixed(2) + ' MB' : '—',
      Creado: createdDate ? createdDate.toISOString().split('T')[0] : '',
      Modificado: modifiedDate ? modifiedDate.toISOString().split('T')[0] : '',
      Ultima_Actualizacion: new Date().toISOString(),

      // Nuevos campos importantes
      Today_Create: isToday,           // true = creado hoy
      Es_Antiguo: isOld,               // true = más de 7 días
      Dias_Desde_Creacion: daysSinceCreation,
      upload: false                    // por defecto false (aún no subido a YouTube)
    }
  };
});

